<?php session_start();require_once __DIR__.'/../../conn.php';require_once __DIR__.'/../../auth.php';requireStaff();
$msg='';$mt='';
if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim(isset($_POST['material_name'])?$_POST['material_name']:'');$q=(int)(isset($_POST['physical_quantity'])?$_POST['physical_quantity']:0);$u=trim(isset($_POST['unit'])?$_POST['unit']:'');if($n===''||$u===''){$msg='Name and unit required.';$mt='error';}else{$s=mysqli_prepare($conn,"INSERT INTO Material(material_name,physical_quantity,unit) VALUES(?,?,?)");mysqli_stmt_bind_param($s,'sis',$n,$q,$u);if(mysqli_stmt_execute($s)){$msg="Material '{$n}' created.";$mt='success';}else{$msg='Insert failed.';$mt='error';}mysqli_stmt_close($s);}}
mysqli_close($conn);
